import { eurosParAn } from '@/domaine/Montant'

export const SEUIL_PROFESSIONNALISATION = eurosParAn(23_000)
import { Either, Option } from 'effect'

import {
	SimulationImpossible,
	SituationIncomplète,
} from '@/contextes/économie-collaborative/domaine/location-de-meublé/erreurs'
import { calculeCotisationsRégimeGénéral } from '@/contextes/économie-collaborative/domaine/location-de-meublé/régime-général'
import { calculeCotisationsTravailleurIndépendant } from '@/contextes/économie-collaborative/domaine/location-de-meublé/régime-travailleur-indépendant'
import {
	estSituationValide,
	RegimeCotisation,
	SituationÉconomieCollaborative,
} from '@/contextes/économie-collaborative/domaine/location-de-meublé/situation'
import { Montant } from '@/domaine/Montant'

import { calculeCotisationsMicroEntreprise } from './régime-micro-entreprise'

export const DEFAULTS = {
	RÉGIME_PAR_DÉFAUT: RegimeCotisation.travailleurIndependant,
	EST_ALSACE_MOSELLE: false,
	PREMIERE_ANNEE: false,
}

/**
 * Calcule les cotisations sociales selon le régime spécifié dans la situation
 * @param situation La situation avec des champs optionnels
 * @returns Un Either contenant soit les cotisations calculées, soit une erreur explicite
 */
export function calculeCotisations(
	situation: SituationÉconomieCollaborative
): Either.Either<Montant<'EuroParAn'>, SimulationImpossible> {
	if (!estSituationValide(situation)) {
		return Either.left(
			new SituationIncomplète({
				message:
					'Impossible de calculer les cotisations sans connaître les recettes',
			})
		)
	}

	const regimeCotisation = Option.getOrElse(
		situation.regimeCotisation,
		() => DEFAULTS.RÉGIME_PAR_DÉFAUT
	)

	switch (regimeCotisation) {
		case RegimeCotisation.regimeGeneral:
			return calculeCotisationsRégimeGénéral(situation)
		case RegimeCotisation.microEntreprise:
			return calculeCotisationsMicroEntreprise(situation)
		case RegimeCotisation.travailleurIndependant:
			return calculeCotisationsTravailleurIndépendant(situation)
	}
}
import { Either, pipe } from 'effect'

import { SEUIL_PROFESSIONNALISATION } from '@/contextes/économie-collaborative/domaine/location-de-meublé/constantes'
import { RecettesInférieuresAuSeuilRequisPourCeRégime } from '@/contextes/économie-collaborative/domaine/location-de-meublé/erreurs'
import { evalueAvecPublicodes } from '@/domaine/engine/engineSingleton'
import { estPlusPetitQue, eurosParAn, Montant } from '@/domaine/Montant'
import {
	AutoEntrepreneurChiffreAffaireDansPublicodes,
	AutoEntrepreneurContexteDansPublicodes,
	AutoEntrepreneurCotisationsEtContributionsDansPublicodes,
} from '@/domaine/publicodes/AutoEntrepreneurContexteDansPublicodes'

import {
	RegimeCotisation,
	SituationÉconomieCollaborativeValide,
} from './situation'

/**
 * Calcule les cotisations sociales pour le régime micro-entreprise
 * @param situation La situation avec des recettes obligatoirement définies
 * @returns Un Either contenant soit les cotisations calculées, soit une erreur explicite
 */
export function calculeCotisationsMicroEntreprise(
	situation: SituationÉconomieCollaborativeValide
): Either.Either<
	Montant<'EuroParAn'>,
	RecettesInférieuresAuSeuilRequisPourCeRégime
> {
	const recettes = situation.recettes.value

	if (pipe(recettes, estPlusPetitQue(SEUIL_PROFESSIONNALISATION))) {
		return Either.left(
			new RecettesInférieuresAuSeuilRequisPourCeRégime({
				recettes,
				seuil: SEUIL_PROFESSIONNALISATION,
				régime: RegimeCotisation.microEntreprise,
			})
		)
	}

	const cotisations = evalueAvecPublicodes<number>(
		{
			...AutoEntrepreneurContexteDansPublicodes,
			...AutoEntrepreneurChiffreAffaireDansPublicodes.fromMontant(recettes),
		},
		AutoEntrepreneurCotisationsEtContributionsDansPublicodes.enEurosParAn
	)

	return Either.right(eurosParAn(cotisations))
}
import { Either, Option, pipe } from 'effect'

import { SEUIL_PROFESSIONNALISATION } from '@/contextes/économie-collaborative/domaine/location-de-meublé/constantes'
import {
	RecettesInférieuresAuSeuilRequisPourCeRégime,
	RecettesSupérieuresAuPlafondAutoriséPourCeRégime,
} from '@/contextes/économie-collaborative/domaine/location-de-meublé/erreurs'
import {
	abattement,
	estPlusGrandQue,
	estPlusPetitQue,
	eurosParAn,
	fois,
	moins,
	Montant,
} from '@/domaine/Montant'

import { DEFAULTS } from './cotisations'
import {
	RegimeCotisation,
	SituationÉconomieCollaborativeValide,
} from './situation'

export const PLAFOND_REGIME_GENERAL = eurosParAn(77_700)
export const TAUX_COTISATION_RG_NORMAL = 0.4742
export const TAUX_COTISATION_RG_ALSACE_MOSELLE = 0.4872
export const ABATTEMENT_REGIME_GENERAL = 0.6

/**
 * Calcule les cotisations sociales pour le régime général
 * @param situation La situation avec des recettes obligatoirement définies
 * @returns Un Either contenant soit les cotisations calculées, soit une erreur explicite
 */
export function calculeCotisationsRégimeGénéral(
	situation: SituationÉconomieCollaborativeValide
): Either.Either<
	Montant<'EuroParAn'>,
	| RecettesInférieuresAuSeuilRequisPourCeRégime
	| RecettesSupérieuresAuPlafondAutoriséPourCeRégime
> {
	const recettes = situation.recettes.value

	const estAlsaceMoselle = Option.getOrElse(
		situation.estAlsaceMoselle,
		() => DEFAULTS.EST_ALSACE_MOSELLE
	)

	const premièreAnnée = Option.getOrElse(
		situation.premièreAnnée,
		() => DEFAULTS.PREMIERE_ANNEE
	)

	if (pipe(recettes, estPlusPetitQue(SEUIL_PROFESSIONNALISATION))) {
		return Either.left(
			new RecettesInférieuresAuSeuilRequisPourCeRégime({
				recettes,
				seuil: SEUIL_PROFESSIONNALISATION,
				régime: RegimeCotisation.regimeGeneral,
			})
		)
	}

	if (pipe(recettes, estPlusGrandQue(PLAFOND_REGIME_GENERAL))) {
		return Either.left(
			new RecettesSupérieuresAuPlafondAutoriséPourCeRégime({
				recettes,
				plafond: PLAFOND_REGIME_GENERAL,
				régime: RegimeCotisation.regimeGeneral,
			})
		)
	}

	const assiette = premièreAnnée
		? pipe(recettes, estPlusGrandQue(SEUIL_PROFESSIONNALISATION))
			? pipe(recettes, moins(SEUIL_PROFESSIONNALISATION))
			: eurosParAn(0)
		: recettes

	const taux = estAlsaceMoselle
		? TAUX_COTISATION_RG_ALSACE_MOSELLE
		: TAUX_COTISATION_RG_NORMAL

	const cotisations = pipe(
		assiette,
		abattement(ABATTEMENT_REGIME_GENERAL),
		fois(taux)
	)

	return Either.right(cotisations)
}
